 const base=M.flatten(DATA,(p,c,t)=>imageFor(p,c,t)), index=new Map(base.map(r=>[r.id,r]));let extras=storage.get('extra-records',[]).filter(r=>r.osm&&r.position&&M.safeExternal(r.url));extras.forEach(r=>index.set(r.id,r));Object.values(storage.get('map-trips',{})).flat().forEach(x=>{if(x.record?.osm&&M.safeExternal(x.record.url))index.set(x.key,x.record);});
