  filters,applyFilters(){drawerMode='nearby';radius=$id('me-radius').value;ticket=$id('me-ticket').value;rating=$id('me-rating').value;closeOverlay();active=null;level='half';draw();},clearFilters(){drawerMode='nearby';radius=ticket=rating=foodKind='';category='all';query='';$id('me-search').value='';closeOverlay();active=null;level='half';draw();},
  foodFilter(){sheet(`<h1>想吃点什么？</h1><p>门店分类来自公开地图记录；菜品资料未必对应附近门店。</p>${[['','全部美食'],['snack','小吃 / 快餐'],['meal','正餐'],['cafe','咖啡']].map(([v,t])=>`<button class="menurow" onclick="MapExplorer.applyFood('${v}')">${t} ↗</button>`).join('')}`);},applyFood(value){drawerMode='nearby';category='food';foodKind=value;closeOverlay();active=null;level='half';draw();if(map&&map.getZoom()<15)map.easeTo({zoom:15,duration:450});},
  loadArea,city(id){category='all';radius=ticket=rating=foodKind=query='';listLimit=70;clearSelectionUrl();destination=null;storage.set('destination','');drawerMode='nearby';clearTripMap();closeOverlay();if($id('me-suggestions'))$id('me-suggestions').hidden=true;query='';active=null;level='peek';if($id('me-search'))$id('me-search').value='';oldChoose(id);mount();fly(cityPoint(id),11);},
