  routePreview,async routeFromSelected(){const start=record($id('me-route-start')?.value),end=record(active);if(start?.position&&end?.position)await fetchRoute(start.position,end.position,start.name);},showRouteMap(){closeOverlay();setLevel('half');if(map&&routeData){const bounds=new ChengjiMap.LngLatBounds();routeData.geometry.coordinates.forEach(p=>bounds.extend(p));map.fitBounds(bounds,{padding:{top:140,bottom:Math.min(drawerHeight()+30,window.innerHeight*.55),left:35,right:75},maxZoom:16,duration:600});}else if(leaf&&leafRoute){leaf.fitBounds(leafRoute.getBounds(),{paddingTopLeft:[25,130],paddingBottomRight:[60,Math.min(drawerHeight()+30,window.innerHeight*.55)]});}},
